function H1G(k){var v="";try{v=source.get(k)}catch(e){try{v=java.get(k)}catch(e2){}};if(v==="null"||v==="undefined")v="";return String(v||"")}
function H1P(k,v){try{source.put(k,String(v))}catch(e){try{java.put(k,String(v))}catch(e2){}}}
function H1DOM(){var d="";try{d=H1G("h1dom")}catch(e){d=""}
  if(!d){d=""}
  if(!d){return "https://www.hanime1.life"}
  if(d.indexOf("http")===0){return d}
  return "https://"+d}
function H1OPT(){return ""}

function H1LIST(java,source,result){
  var d=org.jsoup.Jsoup.parse(String(result))
  var out=[]
  var seen={}
  // template A: sort/search pages
  var cards=d.select('div.video-item-container[title]')
  for(var i=0;i<cards.size();i++){
    var card=cards.get(i)
    var a=card.selectFirst("a.video-link")
    if(!a){continue}
    var u=String(a.attr("href"))
    if(u.indexOf("watch?v=")<0){continue}
    var tt=card.selectFirst("div.title")
    var name=tt?tt.text().trim():""
    if(!name){continue}
    var img=card.selectFirst("img.main-thumb")
    var cover=img?String(img.attr("src")):""
    var dur=card.selectFirst("div.duration")
    var du=dur?dur.text().trim():""
    var sub=card.selectFirst("div.subtitle")
    var author="";var date=""
    if(sub){
      var aa=sub.selectFirst("a")
      author=aa?aa.text().trim():""
      var st=sub.selectFirst("span.subtitle-time")
      date=st?st.text().trim():""
    }
    var st2=card.selectFirst("div.stats-container")
    var views=""
    if(st2){
      var items=st2.select("div.stat-item")
      if(items.size()>1){views=String(items.get(1).text()).trim()}
    }
    if(seen[u]){continue}
    seen[u]=1
    out.push({name:name,u:u,cover:cover,author:author,date:date,du:du,views:views})
  }
  if(out.length>0){return out}
  // template B: genre pages
  var as2=d.select('a[href*="watch?v="]')
  for(var i=0;i<as2.size();i++){
    var a2=as2.get(i)
    var u2=String(a2.attr("href"))
    if(seen[u2]){continue}
    var inner=a2.selectFirst("div.home-rows-videos-div")
    if(!inner){continue}
    var tt2=a2.selectFirst("div.home-rows-videos-title")
    var name2=tt2?tt2.text().trim():""
    if(!name2){continue}
    var img2=a2.selectFirst("img")
    var cover2=img2?String(img2.attr("src")):""
    seen[u2]=1
    out.push({name:name2,u:u2,cover:cover2,author:"",date:"",du:"",views:""})
  }
  return out
}

function H1CUR(java,source,result,baseUrl){
  var d=org.jsoup.Jsoup.parse(String(result))
  var h3=d.selectFirst("h3#shareBtn-title")
  var name=h3?h3.text().trim():""
  var h4s=d.select("div.video-details-wrapper h4")
  var author=""
  for(var i=0;i<h4s.size();i++){
    var t=h4s.get(i).text().trim()
    if(t){author=t;break}
  }
  if(!author){var vn=d.selectFirst("a#video-artist-name");author=vn?vn.text().trim():""}
  var tags=[]
  var tagEls=d.select("div.single-video-tag a")
  for(var i=0;i<tagEls.size();i++){
    var tt=tagEls.get(i).text().trim()
    tt=String(tt).replace(/^#\s*/,"").replace(/\s*\(\d+\)\s*$/,"").trim()
    if(tt&&tt!=="add"&&tt!=="remove"&&tt!=="new"&&tt!=="edit"&&tt.indexOf(".")<0&&tt.length<20&&tags.indexOf(tt)<0){tags.push(tt)}
  }
  var desc=""
  var panel=d.selectFirst("div.video-description-panel")
  if(panel){
    var cap=panel.selectFirst("div.video-caption-text")
    desc=cap?cap.text().trim():""
  }
  var views="";var date=""
  var vd=d.selectFirst("div.video-details-wrapper.hidden-sm")
  if(vd){
    var vt=String(vd.text())
    var vm=vt.match(/\u89c2\u770b\u6b21\u6570\uff1a([^\s&]+)/)
    if(vm){views=vm[1]}
    var dm=vt.match(/(20\d{2}-\d{2}-\d{2})/)
    if(dm){date=dm[1]}
  }
  var cover=""
  var pv=d.selectFirst("video#player")
  if(pv){var po=String(pv.attr("poster"));cover=po}
  var durSec=""
